def S_total(N):
    """Computes S_total(N) = sum_{a=1}^N sum_{b=1}^N floor(ab / (N+1))"""
    sum_val = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            sum_val += (a * b) // (N + 1)
    return sum_val

def T(N):
    """Computes T(N) = (N^3 - N^2 + 2) / 4"""
    return (N**3 - N**2 + 2) / 4

N_values = [1, 2, 3, 4]
results = {}

for N in N_values:
    s = S_total(N)
    t = T(N)
    diff = s - t
    results[N] = {
        "S_total": s,
        "T": t,
        "Difference": diff
    }

print(results)

